arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -d '{"query":"{ __type(name: \"Query\") { fields(includeDeprecated: true) { name args { name type { name kind ofType { name kind } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__type']['fields']:
    if 'attach' in f['name'].lower() or 'comment' in f['name'].lower() or f['name']=='issue':
        args=f['args']
        if any('attach' in f['name'].lower() for _ in [1]):
            print(f['name'], [(a['name'], json.dumps(a['type'])) for a in args])
"

